const crypto = require('crypto');

const MAX_SKEW_SECONDS = 300;
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'] || '';

let raw = '';
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
}

let reason = null;
if (!secret) reason = 'secret not configured';
else if (!raw) reason = 'empty body';
else if (!timestamp || !/^\d+$/.test(timestamp)) reason = 'missing timestamp';
else if (Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_SKEW_SECONDS) reason = 'stale timestamp';
else {
  const expected = Buffer.from('sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex'));
  const given = Buffer.from(signature);
  if (expected.length !== given.length || !crypto.timingSafeEqual(expected, given)) reason = 'bad signature';
}

if (reason) return [{ json: { valid: false, reason } }];
return [{ json: { valid: true, payload: JSON.parse(raw) } }];

const KEEP_DAYS = 7;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const now = Date.now();
for (const [id, at] of Object.entries(store.seen)) {
  if (now - at > KEEP_DAYS * 86400000) delete store.seen[id];
}

const payload = $input.first().json.payload;
const duplicate = Boolean(store.seen[payload.eventId]);
if (!duplicate) store.seen[payload.eventId] = now;

return [{ json: { duplicate, payload } }];

const p = $input.first().json.payload;
const tool = p.loan.toolName;
const dates = p.loan.startDate === p.loan.endDate ? p.loan.startDate : p.loan.startDate + ' to ' + p.loan.endDate;

const templates = {
  requested: [`${p.counterpartName} wants to borrow your ${tool}`, `${p.counterpartName} asked to borrow your ${tool} for ${dates}. Open LendLoop to approve or decline.`],
  approved: [`Your request for the ${tool} was approved`, `${p.counterpartName} approved your request for ${dates}. Enjoy, and remember to bring it back on time.`],
  declined: [`Your request for the ${tool} was declined`, `${p.counterpartName} could not lend the ${tool} for ${dates}. Maybe another neighbor has one.`],
  cancelled_by_borrower: [`${p.counterpartName} cancelled a request`, `${p.counterpartName} no longer needs your ${tool} for ${dates}.`],
  listing_removed: [`The ${tool} is no longer available`, `The listing was removed, so your request for ${dates} was cancelled.`],
  returned: [`Thanks for returning the ${tool}`, `${p.counterpartName} marked the ${tool} as returned.`],
};

const [subject, text] = templates[p.event] || [`Update on the ${tool}`, `Your loan is now ${p.loan.status}.`];
return [{ json: { eventId: p.eventId, to: p.recipient.email, name: p.recipient.name, subject, text: `Hi ${p.recipient.name},\n\n${text}\n\nLendLoop` } }];

const msg = $input.first().json;
const [user, domain] = msg.to.split('@');
const masked = user.slice(0, 1) + '***@' + domain;

console.log(`[mock-notify] ${msg.eventId} to ${masked}: ${msg.subject}`);

return [{ json: { eventId: msg.eventId, channel: 'mock-log', to: masked, subject: msg.subject } }];
